Console.WriteLine($"Got typed metadata  : {personInfo.Type.Name}  (kind: {personInfo.Kind})");

// Round-trip to prove it works
var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
var back = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Round-tripped       : {back}");

